    reason      TEXT,               -- 'expired' / 'revoked' / 'grantor_not_active_admin' / 'delegate_not_active_member'
    created_at  INTEGER NOT NULL,
    expires_at  INTEGER NOT NULL,
    ended_at    INTEGER
);
